/// <summary>
/// PricingAttribute of table <c>MCRCustCategory</c> field CategoryHierarchy.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(MCRCustCategory, CategoryHierarchy))]
internal class GUPPricingAttributeMCRCustCategoryCategoryHierarchy extends GUPPricingAttributeMCRCustCategory implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(MCRCustCategory, CategoryHierarchy);
}

public str getRefValue(Str _defaultValue)
{
    MCRCustCategoryHierarchy custCategoryHierarchy;
    str ret = '';
    boolean isFirstAttributeToAppend = true;
    Query query = new Query();
    query.addDataSource(tableNum(MCRCustCategoryHierarchy)).addRange(fieldNum(MCRCustCategoryHierarchy, RecId)).value(_defaultValue);
    QueryRun qr = new QueryRun(query);
    while (qr.next())
    {
        custCategoryHierarchy = qr.get(tableNum(MCRCustCategoryHierarchy), 1);
        if (!isFirstAttributeToAppend)
        {
            ret += ',';
        }
        else
        {
            isFirstAttributeToAppend = false;
        }
        ret += custCategoryHierarchy.name;
    }

    return ret;        
}

public boolean validate(Str _defaultValue)
{
    var recId = str2Int64(_defaultValue);
    return MCRCustCategoryHierarchy::find(recId) ? true : false;
}

public void lookupAllowedValues(object _formStringControl)
{
    GUPMCRCustCategoryHierarchyLookup custCategoryHierarchyLookup = new GUPMCRCustCategoryHierarchyLookup(true);
    custCategoryHierarchyLookup.performLookup(_formStringControl);

}
